use vstd::prelude::*;

verus! {
    fn array_to_seq(a: &[i32]) -> (s: Vec<i32>)
        ensures
            s.len() == a.len() && forall|i: nat| (i < a.len() as nat) ==> (s[i as usize] == a[i as usize])
    {
        let mut s: Vec<i32> = Vec::new();
        let len = a.len();
        s.reserve(len); // Reserve space for the elements

        let mut idx: usize = 0;
        while idx < len
            invariant
                idx <= len,
                s.len() == idx,
                forall|i: nat| (i < idx as nat) ==> (s[i as usize] == a[i as usize]),
            decreases len - idx,
        {
            s.push(a[idx]); // Push the current element from a to s
            idx += 1; // Move to the next index
        }
        
        s // Return the populated vector
    }
}

